    if not (t0 - 0.5 <= t < t1): continue
    rel = (t - t0) * 1000
    if 'fragment run started' in l:
        out.append((rel, f"START  {re.search(r'role=\"(\\w+)\"', l).group(1):6s} cn={re.search(r'cn=(\S+)', l).group(1)} fid=..{re.search(r'fragment_instance_id=([0-9a-f-]{36})', l).group(1)[-4:]} inputs={re.search(r'inputs=(\d+)', l).group(1)} outputs={re.search(r'outputs=(\d+)', l).group(1)}"))
    elif 'fragment run finished' in l or 'fragment run failed' in l:
        out.append((rel, f"FINISH {re.search(r'role=\"(\\w+)\"', l).group(1):6s} cn={re.search(r'cn=(\S+)', l).group(1)} fid=..{re.search(r'fragment_instance_id=([0-9a-f-]{36})', l).group(1)[-4:]} elapsed={re.search(r'elapsed_ms=(\d+)', l).group(1)}ms"))
    elif 'exec_plan_fragment' in l and 'close' in l:
        peer = re.search(r'peer=(\S+)\}', l); b = re.search(r'time.busy=(\S+)', l); i = re.search(r'time.idle=(\S+)', l)
        out.append((rel, f"RPC exec_plan_fragment close peer={peer.group(1) if peer else '?'} busy={dur_ms(b.group(1)) if b else '?'}ms idle={dur_ms(i.group(1)) if i else '?'}ms"))
    elif 'transmitted batches via nixl' in l:
        out.append((rel, "TX " + re.sub(r'^.*agent_tier: transmitted batches via nixl ', '', l).strip()[:160]))
    elif 'received remote batches' in l:
        out.append((rel, "RX " + re.sub(r'^.*engine: ', '', l).strip()[:120]))
    elif 'fetch_data' in l and 'close' in l:
        out.append((rel, "RPC fetch_data close"))
    elif 'cancel_plan_fragment' in l and 'close' in l:
        pass
    elif 'declared input stream cardinality' in l or 'relayed native batches' in l:
        out.append((rel, "   " + re.sub(r'^.*engine: ', '', l).strip()[:120]))
out.sort()
print(f"### {arm.split('/')[-1]} {want} client ms={r['ms']} (times are ms since client start)")
for rel, s in out: print(f"{rel:8.1f}  {s}")
EOF
